-- ============================================================
-- Phase 5A: Fix search_path on 8 mutable functions
-- ============================================================
ALTER FUNCTION public.set_updated_at()               SET search_path = public;
ALTER FUNCTION public.catalog_set_updated_at()       SET search_path = public;
ALTER FUNCTION public.tg_pfs_updated_at()            SET search_path = public;
ALTER FUNCTION public.tg_pofl_updated_at()           SET search_path = public;
ALTER FUNCTION public.tg_block_pofl_delete()         SET search_path = public;
ALTER FUNCTION public.normalizar_alvo(text)          SET search_path = public;
ALTER FUNCTION public.fn_calc_os_faturamento_totals() SET search_path = public;
ALTER FUNCTION public.fn_validate_envase_cq()        SET search_path = public;

-- ============================================================
-- Phase 5B: Hide matviews from Data API, expose via regular views
-- ============================================================
-- 1) Rename matviews to mv_* so we can create views with old names
ALTER MATERIALIZED VIEW public.vw_esteira_laboratorio   RENAME TO mv_esteira_laboratorio;
ALTER MATERIALIZED VIEW public.vw_fluxo_visita_tecnica  RENAME TO mv_fluxo_visita_tecnica;

-- 2) Revoke Data API from the raw matview
REVOKE ALL ON public.mv_esteira_laboratorio  FROM anon, authenticated;
REVOKE ALL ON public.mv_fluxo_visita_tecnica FROM anon, authenticated;

-- 3) Update the cron refresh jobs to the new matview names
SELECT cron.unschedule('refresh-mv-esteira-laboratorio')
  WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname='refresh-mv-esteira-laboratorio');
SELECT cron.unschedule('refresh-mv-fluxo-visita-tecnica')
  WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname='refresh-mv-fluxo-visita-tecnica');

SELECT cron.schedule(
  'refresh-mv-esteira-laboratorio', '*/5 * * * *',
  $$REFRESH MATERIALIZED VIEW public.mv_esteira_laboratorio;$$
);
SELECT cron.schedule(
  'refresh-mv-fluxo-visita-tecnica', '*/5 * * * *',
  $$REFRESH MATERIALIZED VIEW public.mv_fluxo_visita_tecnica;$$
);

-- 4) Recreate the old public names as regular views that select from matview
CREATE OR REPLACE VIEW public.vw_esteira_laboratorio  AS SELECT * FROM public.mv_esteira_laboratorio;
CREATE OR REPLACE VIEW public.vw_fluxo_visita_tecnica AS SELECT * FROM public.mv_fluxo_visita_tecnica;

GRANT SELECT ON public.vw_esteira_laboratorio  TO anon, authenticated;
GRANT SELECT ON public.vw_fluxo_visita_tecnica TO anon, authenticated;

DROP VIEW IF EXISTS public.vw_esteira_laboratorio;
DROP VIEW IF EXISTS public.vw_fluxo_visita_tecnica;

CREATE VIEW public.vw_esteira_laboratorio
  WITH (security_invoker = true)
  AS SELECT * FROM public.mv_esteira_laboratorio;

CREATE VIEW public.vw_fluxo_visita_tecnica
  WITH (security_invoker = true)
  AS SELECT * FROM public.mv_fluxo_visita_tecnica;

GRANT SELECT ON public.vw_esteira_laboratorio  TO anon, authenticated;
GRANT SELECT ON public.vw_fluxo_visita_tecnica TO anon, authenticated;

-- Fase 6A
DO $$
DECLARE r record;
BEGIN
  FOR r IN
    SELECT p.oid::regprocedure::text AS sig
    FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
    WHERE n.nspname='public' AND p.prosecdef=true AND p.prorettype='trigger'::regtype
  LOOP
    EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM anon, authenticated, PUBLIC', r.sig);
  END LOOP;
END $$;

-- Fase 6B
DO $$
DECLARE r record;
BEGIN
  FOR r IN
    SELECT p.oid::regprocedure::text AS sig
    FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
    WHERE n.nspname='public' AND p.prosecdef=true
      AND p.prorettype <> 'trigger'::regtype
      AND p.proname NOT IN ('rpc_validar_comprovante_entrega','rpc_validar_rastreio_produto')
      AND has_function_privilege('anon', p.oid, 'EXECUTE')
  LOOP
    EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM anon, PUBLIC', r.sig);
  END LOOP;
END $$;

GRANT EXECUTE ON FUNCTION public.rpc_validar_comprovante_entrega(uuid) TO anon, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_validar_rastreio_produto(uuid)   TO anon, authenticated;

-- Fase 6C: SECURITY DEFINER views → security_invoker
DO $$
DECLARE v_def text;
BEGIN
  -- _src_vw_esteira_laboratorio: recreate in-place using CREATE OR REPLACE (preserves matview dependency)
  SELECT pg_get_viewdef('public._src_vw_esteira_laboratorio'::regclass, true) INTO v_def;
  EXECUTE 'CREATE OR REPLACE VIEW public._src_vw_esteira_laboratorio WITH (security_invoker=true) AS ' || v_def;
  REVOKE ALL ON public._src_vw_esteira_laboratorio FROM anon, authenticated, PUBLIC;

  -- vw_os_integridade_esteira: same approach
  SELECT pg_get_viewdef('public.vw_os_integridade_esteira'::regclass, true) INTO v_def;
  EXECUTE 'CREATE OR REPLACE VIEW public.vw_os_integridade_esteira WITH (security_invoker=true) AS ' || v_def;
  GRANT SELECT ON public.vw_os_integridade_esteira TO anon, authenticated;
END $$;

-- Fase 6D: tighten always-true audit policies
DROP POLICY IF EXISTS "System can insert audit logs" ON public.audit_senha_log;
CREATE POLICY "System can insert audit logs" ON public.audit_senha_log
  FOR INSERT WITH CHECK (auth.uid() IS NOT NULL);

DROP POLICY IF EXISTS "catalog_audit_insert_any" ON public.catalog_technical_audit_logs;
CREATE POLICY "catalog_audit_insert_any" ON public.catalog_technical_audit_logs
  FOR INSERT WITH CHECK (auth.uid() IS NOT NULL);

-- FASE 1: Reduzir disk I/O — refresh MVs de 5min para 30min + RPC manual

-- Task 1: Reagendar jobs de refresh
DO $$ BEGIN PERFORM cron.unschedule('refresh-mv-esteira-laboratorio'); EXCEPTION WHEN OTHERS THEN NULL; END $$;
DO $$ BEGIN PERFORM cron.unschedule('refresh-mv-fluxo-visita-tecnica'); EXCEPTION WHEN OTHERS THEN NULL; END $$;

SELECT cron.schedule(
  'refresh-mv-esteira-laboratorio',
  '*/30 * * * *',
  $$REFRESH MATERIALIZED VIEW public.mv_esteira_laboratorio;$$
);

SELECT cron.schedule(
  'refresh-mv-fluxo-visita-tecnica',
  '*/30 * * * *',
  $$REFRESH MATERIALIZED VIEW public.mv_fluxo_visita_tecnica;$$
);

-- Task 2: RPC manual para admin/gestor
CREATE TABLE IF NOT EXISTS public.bi_refresh_audit (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  executed_by uuid NOT NULL,
  executed_at timestamptz NOT NULL DEFAULT now(),
  target text NOT NULL,
  duration_ms integer,
  success boolean NOT NULL DEFAULT true,
  error_message text
);

GRANT SELECT ON public.bi_refresh_audit TO authenticated;
GRANT ALL ON public.bi_refresh_audit TO service_role;
ALTER TABLE public.bi_refresh_audit ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Admins e gestores visualizam auditoria de refresh BI" ON public.bi_refresh_audit;
CREATE POLICY "Admins e gestores visualizam auditoria de refresh BI"
  ON public.bi_refresh_audit FOR SELECT TO authenticated
  USING (public.has_role(auth.uid(), 'administrador') OR public.has_role(auth.uid(), 'gestor'));

CREATE OR REPLACE FUNCTION public.rpc_refresh_bi_operacional()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_start timestamptz;
  v_dur integer;
  v_result jsonb := '{}'::jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;
  IF NOT (public.has_role(v_uid, 'administrador') OR public.has_role(v_uid, 'gestor')) THEN
    RAISE EXCEPTION 'Acesso negado: somente administrador ou gestor';
  END IF;

  v_start := clock_timestamp();
  BEGIN
    REFRESH MATERIALIZED VIEW public.mv_esteira_laboratorio;
    v_dur := EXTRACT(MILLISECOND FROM (clock_timestamp() - v_start))::int;
    INSERT INTO public.bi_refresh_audit(executed_by, target, duration_ms, success)
      VALUES (v_uid, 'mv_esteira_laboratorio', v_dur, true);
    v_result := v_result || jsonb_build_object('mv_esteira_laboratorio', jsonb_build_object('ok', true, 'duration_ms', v_dur));
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO public.bi_refresh_audit(executed_by, target, success, error_message)
      VALUES (v_uid, 'mv_esteira_laboratorio', false, SQLERRM);
    v_result := v_result || jsonb_build_object('mv_esteira_laboratorio', jsonb_build_object('ok', false, 'error', SQLERRM));
  END;

  v_start := clock_timestamp();
  BEGIN
    REFRESH MATERIALIZED VIEW public.mv_fluxo_visita_tecnica;
    v_dur := EXTRACT(MILLISECOND FROM (clock_timestamp() - v_start))::int;
    INSERT INTO public.bi_refresh_audit(executed_by, target, duration_ms, success)
      VALUES (v_uid, 'mv_fluxo_visita_tecnica', v_dur, true);
    v_result := v_result || jsonb_build_object('mv_fluxo_visita_tecnica', jsonb_build_object('ok', true, 'duration_ms', v_dur));
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO public.bi_refresh_audit(executed_by, target, success, error_message)
      VALUES (v_uid, 'mv_fluxo_visita_tecnica', false, SQLERRM);
    v_result := v_result || jsonb_build_object('mv_fluxo_visita_tecnica', jsonb_build_object('ok', false, 'error', SQLERRM));
  END;

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_refresh_bi_operacional() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_refresh_bi_operacional() TO authenticated;

-- Task 3: Blindar permissões das MVs (anon sem acesso; authenticated OK via wrapper vw_*)
REVOKE ALL ON public.mv_esteira_laboratorio FROM PUBLIC, anon;
REVOKE ALL ON public.mv_fluxo_visita_tecnica FROM PUBLIC, anon;
GRANT SELECT ON public.mv_esteira_laboratorio TO authenticated;
GRANT SELECT ON public.mv_fluxo_visita_tecnica TO authenticated;

REVOKE ALL ON public.vw_esteira_laboratorio FROM PUBLIC, anon;
REVOKE ALL ON public.vw_fluxo_visita_tecnica FROM PUBLIC, anon;
GRANT SELECT ON public.vw_esteira_laboratorio TO authenticated;
GRANT SELECT ON public.vw_fluxo_visita_tecnica TO authenticated;

-- FASE 4: BI seguro — filtro por perfil nas views wrapper

-- 1) Revogar acesso direto às materialized views (força uso via vw_*)
REVOKE ALL ON public.mv_esteira_laboratorio FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.mv_fluxo_visita_tecnica FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.mv_esteira_laboratorio TO service_role;
GRANT SELECT ON public.mv_fluxo_visita_tecnica TO service_role;

-- 2) Helper: perfis internos que podem ver o BI global
CREATE OR REPLACE FUNCTION public.can_view_bi_operacional(_uid uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT _uid IS NOT NULL AND (
    public.has_role(_uid, 'administrador')
    OR public.has_role(_uid, 'gestor')
    OR public.has_role(_uid, 'administrativo')
    OR public.has_role(_uid, 'producao')
    OR public.has_role(_uid, 'financeiro')
    OR public.has_role(_uid, 'consultor_tecnico')
    OR public.has_role(_uid, 'tecnico_agronomo')
  );
$$;
REVOKE ALL ON FUNCTION public.can_view_bi_operacional(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_view_bi_operacional(uuid) TO authenticated;

-- 3) Recriar wrapper views com filtro por perfil embutido (executam como owner = postgres, lendo a MV; filtro no WHERE)
DROP VIEW IF EXISTS public.vw_esteira_laboratorio CASCADE;
CREATE VIEW public.vw_esteira_laboratorio AS
  SELECT m.*
  FROM public.mv_esteira_laboratorio m
  WHERE
    -- Perfis executivos/operacionais/financeiro: visão global
    public.has_role(auth.uid(), 'administrador')
    OR public.has_role(auth.uid(), 'gestor')
    OR public.has_role(auth.uid(), 'administrativo')
    OR public.has_role(auth.uid(), 'producao')
    OR public.has_role(auth.uid(), 'financeiro')
    -- Consultor/técnico: apenas seus clientes
    OR (
      (public.has_role(auth.uid(), 'consultor_tecnico') OR public.has_role(auth.uid(), 'tecnico_agronomo'))
      AND m.cliente_id = ANY (public.get_cliente_ids_for_user(auth.uid()))
    );

DROP VIEW IF EXISTS public.vw_fluxo_visita_tecnica CASCADE;
CREATE VIEW public.vw_fluxo_visita_tecnica AS
  SELECT m.*
  FROM public.mv_fluxo_visita_tecnica m
  WHERE
    public.has_role(auth.uid(), 'administrador')
    OR public.has_role(auth.uid(), 'gestor')
    OR public.has_role(auth.uid(), 'administrativo')
    OR public.has_role(auth.uid(), 'producao')
    OR public.has_role(auth.uid(), 'financeiro')
    OR (
      (public.has_role(auth.uid(), 'consultor_tecnico') OR public.has_role(auth.uid(), 'tecnico_agronomo'))
      AND (m.consultor_id = auth.uid() OR m.cliente_id = ANY (public.get_cliente_ids_for_user(auth.uid())))
    );

REVOKE ALL ON public.vw_esteira_laboratorio FROM PUBLIC, anon;
REVOKE ALL ON public.vw_fluxo_visita_tecnica FROM PUBLIC, anon;
GRANT SELECT ON public.vw_esteira_laboratorio TO authenticated;
GRANT SELECT ON public.vw_fluxo_visita_tecnica TO authenticated;

-- 4) Índices auxiliares (não recriam se já existem)
CREATE INDEX IF NOT EXISTS idx_mv_esteira_fazenda ON public.mv_esteira_laboratorio (fazenda_id);
CREATE INDEX IF NOT EXISTS idx_mv_esteira_produto ON public.mv_esteira_laboratorio (produto_id);
CREATE INDEX IF NOT EXISTS idx_mv_esteira_microrganismo ON public.mv_esteira_laboratorio (microrganismo_id);
CREATE INDEX IF NOT EXISTS idx_mv_esteira_entrega_status ON public.mv_esteira_laboratorio (entrega_status);

CREATE INDEX IF NOT EXISTS idx_mv_fluxo_fazenda ON public.mv_fluxo_visita_tecnica (fazenda_id);
CREATE INDEX IF NOT EXISTS idx_mv_fluxo_talhao ON public.mv_fluxo_visita_tecnica (talhao_id);

CREATE OR REPLACE FUNCTION public.publish_planning_to_lab(p_planning_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_pl public.production_planning%ROWTYPE;
  v_result jsonb;
  v_count int;
  v_uid uuid := auth.uid();
BEGIN
  IF NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'producao') OR public.has_role(v_uid,'gestor')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT * INTO v_pl FROM public.production_planning WHERE id = p_planning_id FOR UPDATE;
  IF v_pl.id IS NULL THEN RAISE EXCEPTION 'planning_not_found'; END IF;

  IF v_pl.status IN ('em_producao','produzido','entregue') THEN
    RAISE EXCEPTION 'already_published';
  END IF;

  IF v_pl.planned_start_date IS NOT NULL AND v_pl.planned_finish_date IS NOT NULL
     AND v_pl.planned_finish_date < v_pl.planned_start_date THEN
    RAISE EXCEPTION 'invalid_dates';
  END IF;

  PERFORM public._validate_planning_integrity(v_pl.partner_order_id);

  v_result := public.generate_production_orders_from_partner(v_pl.partner_order_id);
  v_count := COALESCE((v_result->>'os_created')::int, 0);

  IF v_count = 0 AND NOT EXISTS (
    SELECT 1 FROM public.production_order_link WHERE planning_id = v_pl.id
  ) THEN
    RAISE EXCEPTION 'no_items';
  END IF;

  INSERT INTO public.laboratorio_esteira_eventos (os_id, origem_os, acao, etapa_nova, usuario_id, observacao)
  SELECT os.id, COALESCE(os.origem,'b2b'), 'demanda_publicada', 'recebido_no_lab', v_uid,
         'Planejamento publicado no Cockpit'
  FROM public.ordens_servico os
  WHERE os.partner_order_id = v_pl.partner_order_id
    AND NOT EXISTS (
      SELECT 1 FROM public.laboratorio_esteira_eventos e
      WHERE e.os_id = os.id AND e.acao = 'demanda_publicada'
    );

  UPDATE public.production_planning
     SET status = 'planejado', updated_at = now()
   WHERE id = v_pl.id AND status IN ('aguardando_planejamento','replanejar');

  INSERT INTO public.production_timeline_events (partner_order_id, event_type, actor_id, meta)
  VALUES (v_pl.partner_order_id, 'planejamento_publicado', v_uid,
          jsonb_build_object('planning_id', v_pl.id, 'os_created', v_count));

  INSERT INTO public.partner_order_audit_logs (order_id, partner_id, usuario_id, acao, dados_novos)
  VALUES (v_pl.partner_order_id, v_pl.partner_id, v_uid, 'planejamento_publicado',
          jsonb_build_object('planning_id', v_pl.id, 'os_created', v_count));

  -- Refresh Cockpit materialized view so new OS appear immediately.
  -- Wrapped so a refresh error never rolls back publication (cron still refreshes every 5 min).
  BEGIN
    REFRESH MATERIALIZED VIEW public.mv_esteira_laboratorio;
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN jsonb_build_object('ok', true, 'planning_id', v_pl.id, 'os_created', v_count);
END
$$;

REVOKE ALL ON FUNCTION public.publish_planning_to_lab(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.publish_planning_to_lab(uuid) TO authenticated, service_role;


CREATE OR REPLACE FUNCTION public.lab_request_replanning(p_os_id uuid, p_motivo text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_partner_order_id uuid;
  v_planning_id uuid;
  v_partner_id uuid;
  v_uid uuid := auth.uid();
BEGIN
  IF p_motivo IS NULL OR length(trim(p_motivo)) < 3 THEN RAISE EXCEPTION 'reason_required'; END IF;
  IF NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'producao')
          OR public.has_role(v_uid,'gestor') OR public.has_role(v_uid,'laboratorio')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT partner_order_id INTO v_partner_order_id FROM public.ordens_servico WHERE id = p_os_id FOR UPDATE;
  IF v_partner_order_id IS NULL THEN RAISE EXCEPTION 'order_not_found'; END IF;

  SELECT id, partner_id INTO v_planning_id, v_partner_id
  FROM public.production_planning WHERE partner_order_id = v_partner_order_id FOR UPDATE;
  IF v_planning_id IS NULL THEN RAISE EXCEPTION 'planning_not_found'; END IF;

  INSERT INTO public.laboratorio_esteira_eventos (os_id, acao, etapa_nova, usuario_id, observacao)
  VALUES (p_os_id, 'replanejamento_solicitado', 'replanejar', v_uid, p_motivo);

  UPDATE public.production_planning
     SET status = 'replanejar', updated_at = now(),
         production_notes = COALESCE(production_notes || E'\n', '') ||
                            '[' || to_char(now(),'DD/MM/YYYY HH24:MI') || '] Replanejamento: ' || p_motivo
   WHERE id = v_planning_id;

  INSERT INTO public.production_timeline_events (partner_order_id, event_type, actor_id, meta)
  VALUES (v_partner_order_id, 'replanejamento_solicitado', v_uid,
          jsonb_build_object('planning_id', v_planning_id, 'os_id', p_os_id, 'motivo', p_motivo));

  INSERT INTO public.partner_order_audit_logs (order_id, partner_id, usuario_id, acao, dados_novos)
  VALUES (v_partner_order_id, v_partner_id, v_uid, 'replanejamento_solicitado',
          jsonb_build_object('planning_id', v_planning_id, 'os_id', p_os_id, 'motivo', p_motivo));

  BEGIN
    REFRESH MATERIALIZED VIEW public.mv_esteira_laboratorio;
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN jsonb_build_object('ok', true, 'planning_id', v_planning_id);
END
$$;

REVOKE ALL ON FUNCTION public.lab_request_replanning(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.lab_request_replanning(uuid, text) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.refresh_esteira_laboratorio()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  REFRESH MATERIALIZED VIEW public.mv_esteira_laboratorio;
END;
$function$;

REVOKE ALL ON FUNCTION public.refresh_esteira_laboratorio() FROM PUBLIC, anon;
